155	local z_crc_t multmodp(z_crc_t a, z_crc_t b) {
156	    z_crc_t m, p;
157	
158	    m = (z_crc_t)1 << 31;
159	    p = 0;
160	    for (;;) {
161	        if (a & m) {
162	            p ^= b;
163	            if ((a & (m - 1)) == 0)
164	                break;
165	        }
166	        m >>= 1;
167	        b = b & 1 ? (b >> 1) ^ POLY : b >> 1;
168	    }
169	    return p;
170	}
